let stored = flow.get(node.id+'stored') || {}
let previousSum = flow.get(node.id+'previousSum')

if (Number(msg.payload)) {
    stored[msg.topic] = msg.payload
} else {
    if (msg.payload === 'delete' && stored[msg.topic]) {
        delete stored[msg.topic]
    }
}

flow.set(node.id+'stored', stored)
msg.payload = Object.keys(stored).reduce((sum, key) => sum + parseFloat(stored[key] || 0), 0);
if (env.get('onlychanges') && ( previousSum === msg.payload )) {
    return
}
flow.set(node.id+'previousSum', msg.payload)
msg.rate = (Number(env.get('rate')) || 5) * 1000 

msg.topic = env.get('topic')

if (env.get('expected') > 0 && Object.keys(stored).length < env.get('expected')) {
    return
}

return msg;
